create extension if not exists pgcrypto;
create table organisation(id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,created_at timestamptz not null default now());
create table identity_record(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references organisation(id) on delete cascade,external_key text not null,display_name text not null,email text,identity_type text not null check(identity_type in('employee','contractor','service')),manager_id uuid references identity_record(id),active boolean not null default true,unique(organisation_id,external_key));
create table governed_application(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references organisation(id) on delete cascade,name text not null,connector_type text not null,owner_identity_id uuid references identity_record(id),unique(organisation_id,name));
create table entitlement(id uuid primary key default gen_random_uuid(),application_id uuid not null references governed_application(id) on delete cascade,external_key text not null,name text not null,privileged boolean not null default false,description text not null default '',unique(application_id,external_key));
create table entitlement_assignment(identity_id uuid not null references identity_record(id) on delete cascade,entitlement_id uuid not null references entitlement(id) on delete cascade,assigned_at timestamptz not null,last_used_at timestamptz,source text not null,primary key(identity_id,entitlement_id));
create table campaign(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references organisation(id) on delete cascade,name text not null,scope jsonb not null,state text not null default 'draft' check(state in('draft','generating','active','closing','closed')),due_at timestamptz,created_at timestamptz not null default now());
create table certification_item(id uuid primary key default gen_random_uuid(),campaign_id uuid not null references campaign(id) on delete cascade,identity_id uuid not null references identity_record(id),entitlement_id uuid not null references entitlement(id),reviewer_id uuid references identity_record(id),risk_score integer not null check(risk_score between 0 and 100),decision text check(decision in('approve','revoke','delegate','exception')),decided_at timestamptz,unique(campaign_id,identity_id,entitlement_id));
create table decision_ledger(id bigint generated always as identity primary key,organisation_id uuid not null references organisation(id) on delete cascade,certification_item_id uuid not null references certification_item(id),actor_subject text not null,decision text not null,reason text not null,previous_hash text,record_hash text not null,occurred_at timestamptz not null default now());
create function prevent_ledger_change() returns trigger language plpgsql as $$ begin raise exception 'decision ledger is append-only'; end $$;
create trigger decision_ledger_immutable before update or delete on decision_ledger for each row execute function prevent_ledger_change();
create table audit_event(id bigint generated always as identity primary key,organisation_id uuid not null references organisation(id) on delete cascade,actor_id text not null,action text not null,entity_type text not null,entity_id text not null,payload jsonb not null default '{}'::jsonb,occurred_at timestamptz not null default now());
create table role_policy(organisation_id uuid not null references organisation(id) on delete cascade,role_key text not null,permissions text[] not null default '{}',updated_by text not null,updated_at timestamptz not null default now(),primary key(organisation_id,role_key));
